@startuml

class Department {}

class Room {
  +number: int
}

class Bed {
  +number: int
}

class BedCategory {
  +price: float
}

enum StayType {
  RH
  RNH
  SF
}

class Inhabitant {
  +name: string
  +registrationDate: date
}

class Stay {
  +startDate: date
  +endDate: date
  +isSuspended: boolean
  +isInvalidated: boolean
}

class Registration {
  +identificationData: string
  +assessmentResults: string
}

class WaitingListPosition {
  +position: int
}

class Proposal {
  +proposalDate: date
  +isAccepted: boolean
  +isRefused: boolean
  +isInvalidated: boolean
}

class Invoice {
  +date: date
  +outstandingAmount: float
  +status: string
}

class Payment {
  +amount: float
  +date: datetime
}

class CreditNote {
  +amount: float
}

Department "1" *-- "*" Room
Room "1" *-- "*" Bed
Bed "*" -- "1" BedCategory
Inhabitant "1" -- "*" Stay
Inhabitant "1" -- "1" Registration
Inhabitant "1" -- "*" StayCategoryPosition
StayType -- "*" Stay
Stay "1" -- "*" Invoice
Stay "1" -- "*" Payment
Stay "1" -- "0..1" CreditNote
Invoice "1" -- "*" Payment
Invoice "1" -- "0..1" CreditNote

class StayCategoryPosition {
}

StayCategoryPosition "*" -- "1" StayType

Proposal "*" -- "1" StayType
Proposal "*" -- "1" Inhabitant

@enduml

